css:
#tongsci1-3-3-1-1-metab .mb-body { grid-template-columns: 1080px minmax(0, 1fr); }
#tongsci1-3-3-1-1-metab .mb-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #f5f2ea; }
#tongsci1-3-3-1-1-metab .mb-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-1-1-metab .mb-panel { gap: 10px; }
#tongsci1-3-3-1-1-metab .mb-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; flex: none; }
#tongsci1-3-3-1-1-metab .mb-out b { color: var(--accent); }
#tongsci1-3-3-1-1-metab .mb-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 17px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-1-1-metab .mb-tab thead th { font: 800 17px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
#tongsci1-3-3-1-1-metab .mb-tab thead th.ana { color: #1f6f95; }
#tongsci1-3-3-1-1-metab .mb-tab thead th.cat { color: #b2362b; }
#tongsci1-3-3-1-1-metab .mb-tab thead th:first-child { width: 24%; }
#tongsci1-3-3-1-1-metab .mb-tab tbody th { font: 700 16px/1.2 var(--f-body); text-align: center; border: 1.5px solid var(--rule, #c9ccd3); background: color-mix(in srgb, var(--ink) 4%, var(--paper-2)); }
#tongsci1-3-3-1-1-metab .mb-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 3px 6px; height: 34px; text-align: center; }
#tongsci1-3-3-1-1-metab .mb-tab td b { color: var(--accent); }
section#tongsci1-3-3-1-1-metab.ex.u-done .mb-tab1 { display: none; }

